// sample baked front text (uv origin bottom-left). returns 0/1
float textMask(vec2 uv){
    if(uv.x<0.0||uv.x>1.0||uv.y<0.0||uv.y>1.0) return 0.0;
    int x = clamp(int(uv.x*256.0), 0, 255);
    int y = clamp(int((1.0-uv.y)*72.0), 0, 71);
    int bit = y*256 + x;
    uint word = TXT[bit>>5];
    return float((word >> uint(bit & 31)) & 1u);
}

// ---- crate dimensions, in inches (evaluated in inch-space, then scaled by S) ----
const float WALL  = 0.45;
const vec3  IHALF = vec3(6.50, 5.50, 6.50);             // interior half (13 x 11 x 13)
const vec3  OHALF = vec3(6.95, 5.50, 6.95);             // exterior half (open top)
// vertical bands (y, bottom of crate = -5.5, top = +5.5)
const float MIDC = 0.15, MIDH = 2.15;                   // diamond mesh band  (-2.0 .. +2.3)
const float TOPC = 3.40, TOPH = 1.10;                   // horizontal-rib band (+2.3 .. +4.5)
const float XWIN = 6.20;                                // carve window half (leaves corner posts)

float g_id;   // material id from map()

// diamond mesh carved through z (front/back walls), inside an (x,y) window
float carveZ(vec3 P, float yc, float yh){
    vec2 w = P.xy - vec2(0.0, yc);
    float win = max(abs(w.x)-XWIN, abs(w.y)-yh);
    vec2 r = rot(0.7854)*w;                              // 45° -> square holes become diamonds
    vec2 id = clamp(floor(r/1.65 + 0.5), vec2(-12.0), vec2(12.0));
    float hole = sdPrism(r - 1.65*id, vec2(0.60));
    return max(hole, win);
}
float carveX(vec3 P, float yc, float yh){
    vec2 w = P.zy - vec2(0.0, yc);
    float win = max(abs(w.x)-XWIN, abs(w.y)-yh);
    vec2 r = rot(0.7854)*w;
    vec2 id = clamp(floor(r/1.65 + 0.5), vec2(-12.0), vec2(12.0));
    float hole = sdPrism(r - 1.65*id, vec2(0.60));
    return max(hole, win);
}
// horizontal rib slots in the top band (open gaps between bars)
float slotsZ(vec3 P){
    vec2 w = P.xy - vec2(0.0, TOPC);
    float win = max(abs(w.x)-XWIN, abs(w.y)-TOPH);
    float yy = w.y - 0.55*clamp(floor(w.y/0.55 + 0.5), -5.0, 5.0);
    return max(abs(yy)-0.18, win);
}
float slotsX(vec3 P){
    vec2 w = P.zy - vec2(0.0, TOPC);
    float win = max(abs(w.x)-XWIN, abs(w.y)-TOPH);
    float yy = w.y - 0.55*clamp(floor(w.y/0.55 + 0.5), -5.0, 5.0);
    return max(abs(yy)-0.18, win);
}
// oblong handle hole near the top of front & back (carved through z)
float handle(vec3 P){
    vec2 w = P.xy - vec2(0.0, 4.05);
    vec2 d = abs(w) - vec2(2.30, 0.45);
    return min(max(d.x,d.y),0.0) + length(max(d,0.0)) - 0.35;
}

// crate SDF in inch-space
float crateIn(vec3 P){
    float outer = sdBox(P, OHALF) - 0.12;                // slight rounding for plastic
    // cavity: closed bottom, open top
    float cavTop = OHALF.y + 2.0, cavBot = -OHALF.y + WALL;
    float inner = sdBox(P - vec3(0.0,(cavTop+cavBot)*0.5,0.0),
                        vec3(IHALF.x, (cavTop-cavBot)*0.5, IHALF.z));
    float shell = max(outer, -inner);

    // overhanging top rim lip
    float lipO = sdBox(P - vec3(0.0,4.95,0.0), vec3(OHALF.x+0.28, 0.55, OHALF.z+0.28)) - 0.1;
    float lipI = sdBox(P - vec3(0.0,4.95,0.0), vec3(IHALF.x, 1.6, IHALF.z));
    shell = min(shell, max(lipO, -lipI));

    // raised nameplate plaques on the front (+z) and back (-z) solid base
    float plaqF = sdBox(P - vec3(0.0,-3.65, OHALF.z), vec3(5.70,1.55,0.30)) - 0.04;
    float plaqB = sdBox(P - vec3(0.0,-3.65,-OHALF.z), vec3(5.70,1.55,0.30)) - 0.04;
    shell = min(shell, min(plaqF, plaqB));

    // carve the mesh, rib slots and handle
    float carve = carveZ(P, MIDC, MIDH);
    carve = min(carve, carveX(P, MIDC, MIDH));
    carve = min(carve, slotsZ(P));
    carve = min(carve, slotsX(P));
    carve = min(carve, handle(P));
    shell = max(shell, -carve);
    return shell;
}

float map(vec3 p){
    float d = 1e9; g_id = 0.0;
    float fl = p.y - (-OHALF.y*S);            // floor at crate bottom
    if(fl < d){ d = fl; g_id = 0.0; }
    float cr = S * crateIn(p / S);            // scale crate from inch-space
    if(cr < d){ d = cr; g_id = 1.0; }
    return d;
}

vec3 calcNormal(vec3 p){
    vec2 e = vec2(0.0012, 0.0);
    return normalize(vec3(
        map(p+e.xyy)-map(p-e.xyy),
        map(p+e.yxy)-map(p-e.yxy),
        map(p+e.yyx)-map(p-e.yyx)));
}
float march(vec3 ro, vec3 rd, out float id){
    float t = 0.02; id = -1.0;
    for(int i=0;i<200;i++){
        vec3 p = ro + t*rd;
        float d = map(p);
        if(d < 0.0008){ id = g_id; return t; }
        t += d*0.7;
        if(t > 16.0) break;
    }
    return -1.0;
}
float softShadow(vec3 ro, vec3 rd){
    float res = 1.0, t = 0.04;
    for(int i=0;i<48;i++){
        float h = map(ro + rd*t);
        if(h < 0.001) return 0.04;
        res = min(res, 10.0*h/t);
        t += clamp(h, 0.01, 0.10);
        if(t > 7.0) break;
    }
    return clamp(res, 0.04, 1.0);
}
float ao(vec3 p, vec3 n){
    float occ=0.0, sca=1.0;
    for(int i=0;i<5;i++){
        float hr = 0.01 + 0.10*float(i);
        occ += (hr - map(p+n*hr))*sca; sca *= 0.72;
    }
    return clamp(1.0 - 1.5*occ, 0.0, 1.0);
}

vec3 background(vec3 rd){
    float h = clamp(rd.y*0.5+0.5, 0.0, 1.0);
    return mix(vec3(0.42,0.43,0.46), vec3(0.20,0.22,0.27), h);
}

vec3 material(vec3 p, vec3 n, float id){
    if(id < 0.5){                                  // speckled concrete floor
        vec2 g = p.xz*9.0;
        float sp = hash21(floor(g)) + hash21(floor(g*3.1))*0.5;
        vec3 c = vec3(0.60,0.59,0.575) + (sp-0.7)*0.10;
        return c;
    }
    // red plastic crate (worn matte)
    float wear = 0.85 + 0.15*hash21(floor(p.xz*40.0)+floor(p.y*40.0));
    vec3 red = vec3(0.60,0.085,0.075) * wear;
    red += 0.04*smoothstep(0.3,1.0,n.y);           // slight top sheen
    // embossed warning text on the front (+z) nameplate plaque
    vec3 P = p / S;                                // back to inch-space
    if(P.z > 7.05 && n.z > 0.4 && P.y > -5.3 && P.y < -2.0){
        vec2 tuv = vec2((P.x + 5.6)/11.2, (P.y + 5.20)/3.10);
        float m = textMask(tuv);
        red = mix(red, vec3(0.86,0.84,0.78), m*0.92); // raised cream lettering
    }
    return red;
}

void mainImage(out vec4 O, in vec2 fragCoord){
    vec2 uv = (fragCoord - 0.5*iResolution.xy)/iResolution.y;

    float yaw = 0.30 + 0.14*sin(0.12*iTime);
    float pitch = 0.34;
    if(iMouse.z > 0.0){
        yaw   = -PI + 6.2832*(iMouse.x/iResolution.x);
        pitch = mix(0.05, 1.30, clamp(iMouse.y/iResolution.y, 0.0, 1.0));
    }
    float rad = 5.4;
    vec3 ta = vec3(0.0, -0.02, 0.0);
    vec3 ro = ta + rad*vec3(sin(yaw)*cos(pitch), sin(pitch), cos(yaw)*cos(pitch));
    vec3 ww = normalize(ta-ro);
    vec3 uu = normalize(cross(ww, vec3(0,1,0)));
    vec3 vv = cross(uu, ww);
    vec3 rd = normalize(uv.x*uu + uv.y*vv + 1.9*ww);

    vec3 key = normalize(vec3(-0.55, 0.72, 0.45));
    vec3 col = background(rd);

    float id;
    float t = march(ro, rd, id);
    if(t > 0.0){
        vec3 p = ro + t*rd;
        vec3 n = calcNormal(p);
        vec3 base = material(p, n, id);

        float dif = clamp(dot(n,key), 0.0, 1.0);
        float sh  = softShadow(p + n*0.01, key);
        float occ = ao(p, n);
        vec3  amb = background(n)*0.7;
        float spec = pow(max(dot(reflect(-key,n), -rd), 0.0), 32.0);
        float fres = pow(1.0 - max(dot(n,-rd),0.0), 4.0);

        col  = base*(amb*occ + vec3(1.0,0.96,0.9)*dif*sh*1.1);
        col += vec3(1.0,0.97,0.9)*spec*sh*0.35*(id>0.5?1.0:0.0);
        col += fres*0.06;
        col = mix(col, background(rd), smoothstep(9.0,15.0,t));
    }

    col = (col*(2.51*col+0.03))/(col*(2.43*col+0.59)+0.14);   // ACES
    col = clamp(col, 0.0, 1.0);
    col *= 1.0 - 0.18*dot(uv,uv);                              // vignette
    col = pow(col, vec3(0.4545));
    O = vec4(col, 1.0);
}
